import http.server, threading, socketserver, sys, json

class H(http.server.BaseHTTPRequestHandler):
    def log_message(self, format, *args):
        sys.stderr.write("%s - %s\n" % (self.address_string(), format%args))
    def do_GET(self):
        p=self.path
        if p=="/":
            self.send(200, "text/html", '<html><head><title>t</title></head><body><a href="/ok">ok</a> <a href="/missing">bad</a> <a href="https://example.com/ext">ext</a> <a href="#frag">frag</a> <a href="mailto:foo@bar.com">mail</a> <img src="/img.png"></body></html>')
        elif p=="/ok":
            self.send(200, "text/html", '<html><body><a href="/">home</a><a href="/ok2">ok2</a></body></html>')
        elif p=="/ok2":
            self.send(200, "text/html", '<html><body>ok2</body></html>')
        elif p=="/img.png":
            self.send(200, "image/png", b'\x89PNG')
        elif p=="/missing":
            self.send(404, "text/html", 'not found')
        elif p=="/redirect":
            self.send_response(302); self.send_header("Location","/ok"); self.end_headers()
        elif p=="/redirect-loop":
            self.send_response(302); self.send_header("Location","/redirect-loop"); self.end_headers()
        elif p=="/redir-out":
            self.send_response(302); self.send_header("Location","/ok"); self.end_headers()
        elif p=="/robots.txt":
            self.send(200, "text/plain", "User-agent: *\nDisallow: /private\n")
        elif p=="/sitemap.xml":
            self.send(200, "application/xml", '<?xml version="1.0"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><url><loc>/sitemapped</loc></url></urlset>')
        elif p=="/private":
            self.send(200, "text/html", '<a href="/secret">s</a>')
        elif p=="/secret":
            self.send(200, "text/html", 'secret')
        elif p=="/sitemapped":
            self.send(200, "text/html", '<a href="/ok">ok</a>')
        elif p.startswith("/header-echo"):
            body=json.dumps(dict(self.headers))
            self.send(200, "text/html", body)
        else:
            self.send(404, "text/html", 'nf '+p)
    def send(self, code, ct, body):
        if isinstance(body,str): body=body.encode()
        self.send_response(code); self.send_header("Content-Type",ct); self.send_header("Content-Length",str(len(body))); self.end_headers(); self.wfile.write(body)

class ThreadingHTTPServer(socketserver.ThreadingMixIn, http.server.HTTPServer):
    daemon_threads=True
    allow_reuse_address=True

port=int(sys.argv[1]) if len(sys.argv)>1 else 18080
srv=ThreadingHTTPServer(("127.0.0.1",port), H)
print(f"listening {port}", flush=True)
srv.serve_forever()
