import http.server, socketserver, sys, urllib.parse, json, time

class H(http.server.BaseHTTPRequestHandler):
    def log_message(self, format, *args):
        sys.stderr.write("%s %s headers=%s\n" % (self.command, self.path, dict(self.headers)))
    def do_GET(self): self.handle()
    def do_HEAD(self): self.handle()
    def do_POST(self): self.handle()
    def do_PUT(self): self.handle()
    def do_DELETE(self): self.handle()
    def handle(self):
        u=urllib.parse.urlparse(self.path)
        p=u.path; q=urllib.parse.parse_qs(u.query)
        def get(k,d=""): return q.get(k,[d])[0]
        if p=="/ct":
            ct=get("ct","text/html")
            body=get("body", '<a href="/ok">ok</a>')
            code=int(get("code","200"))
            extra={}
            if get("location"): 
                self.send_response(code); self.send_header("Location", get("location")); self.end_headers(); return
            self._send(code, ct if ct!="NONE" else None, body)
            return
        if p=="/ok":
            self._send(200,"text/html","ok page <a href='/ok2'>2</a>"); return
        if p=="/ok2":
            self._send(200,"text/html","ok2"); return
        if p=="/echo":
            body=json.dumps({"method":self.command,"path":self.path,"headers":{k:v for k,v in self.headers.items()},"body":self.rfile.read(int(self.headers.get('Content-Length',0) or 0)).decode('utf-8','ignore') if self.headers.get('Content-Length') else ""})
            self._send(200,"text/html",'<a href="/ok">ok</a> <!-- '+body+' -->')  # not visible
            return
        if p=="/echohtml":
            # page whose links will be header values? Instead return headers as ?? We'll log server side
            self._send(200,"text/html",'<a href="/ok">ok</a>'); return
        if p=="/redirect":
            n=int(get("n","1")); to=get("to","/ok")
            self.send_response(302); self.send_header("Location",to); self.end_headers(); return
        if p=="/delay":
            time.sleep(float(get("s","1"))); self._send(200,"text/html","delayed"); return
        if p=="/chunked-big":
            body='<a href="/ok">ok</a>'+"x"*int(get("size","20000"))
            self._send(200,"text/html",body); return
        if p=="/missing":
            self._send(404,"text/html","missing"); return
        # generic page maker: /page/<name>?links=/a,/b
        if p.startswith("/page/"):
            links=get("links","")
            html="".join(f'<a href="{l}">x</a>' for l in links.split(",") if l)
            ids=get("ids","")
            for i in ids.split(","):
                if i: html+=f'<div id="{i}">y</div>'
            names=get("names","")
            for i in names.split(","):
                if i: html+=f'<a name="{i}">y</a>'
            self._send(200,"text/html",html); return
        self._send(404,"text/html","nf "+p)
    def _send(self,code,ct,body):
        if isinstance(body,str): body=body.encode()
        self.send_response(code)
        if ct is not None: self.send_header("Content-Type",ct)
        self.send_header("Content-Length",str(len(body)))
        self.end_headers()
        if self.command!="HEAD": 
            try: self.wfile.write(body)
            except: pass

class TS(socketserver.ThreadingMixIn, http.server.HTTPServer):
    daemon_threads=True; allow_reuse_address=True
srv=TS(("127.0.0.1",18085),H)
print("listening 18085",flush=True)
srv.serve_forever()
