package main

import (
	"fmt"
	"os"
)

func main() {
	code, err := runMain(os.Args)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	os.Exit(code)
}

func runMain(argv []string) (int, error) {
	opts, positional, parseErr, help, version := parseArgs(argv[1:])
	if parseErr != nil {
		return 1, parseErr
	}
	if help {
		fmt.Fprint(os.Stdout, helpText(programName(argv)))
		return 0, nil
	}
	if version {
		fmt.Fprintln(os.Stdout, "2.11.1")
		return 0, nil
	}
	if len(positional) != 1 {
		return 1, fmt.Errorf("invalid number of arguments")
	}
	cmd := newCommand(opts)
	failed, err := cmd.run(positional[0])
	if err != nil {
		return 1, err
	}
	if failed {
		return 1, nil
	}
	return 0, nil
}

func programName(argv []string) string {
	if len(argv) == 0 || argv[0] == "" {
		return "executable"
	}
	// Base name without importing path/filepath repeatedly in other files.
	name := argv[0]
	for len(name) > 0 && name[len(name)-1] == '/' {
		name = name[:len(name)-1]
	}
	for i := len(name) - 1; i >= 0; i-- {
		if name[i] == '/' {
			return name[i+1:]
		}
	}
	if name == "" {
		return argv[0]
	}
	return name
}
