func (o *options) setBool(def *flagDef) error {
	switch def.id {
	case "robots": o.FollowRobotsTxt = true
	case "sitemap": o.FollowSitemapXML = true
	case "ignorefrag": o.IgnoreFragments = true
	case "json": o.JSON = true
	case "expverbosejson": o.ExperimentalVerboseJSON = true
	case "junit": o.JUnit = true
	case "verbose": o.Verbose = true
	case "skiptls": o.SkipTLSVerification = true
	case "onepage": o.OnePageOnly = true
	case "help": o.Help = true
