package main

import (
	"sync"
	"time"
)

type semaphore struct {
	ch chan struct{}
}

func newSemaphore(size int) *semaphore {
	return &semaphore{make(chan struct{}, size)}
}

func (s *semaphore) Request() {
	s.ch <- struct{}{}
}

func (s *semaphore) Release() {
	<-s.ch
}

type hostThrottler struct {
	sem *semaphore
}

func newHostThrottler(size int) *hostThrottler {
	return &hostThrottler{newSemaphore(size)}
}

func (h *hostThrottler) Request() {
	h.sem.Request()
}

func (h *hostThrottler) Release() {
	h.sem.Release()
}

type hostThrottlerPool struct {
	mu    sync.Mutex
	size  int
	items map[string]*hostThrottler
}

func newHostThrottlerPool(size int) *hostThrottlerPool {
	return &hostThrottlerPool{size: size, items: map[string]*hostThrottler{}}
}

func (p *hostThrottlerPool) Get(host string) *hostThrottler {
	p.mu.Lock()
	defer p.mu.Unlock()
	if h, ok := p.items[host]; ok {
		return h
	}
	h := newHostThrottler(p.size)
	p.items[host] = h
	return h
}

type rateLimiter struct {
	mu       sync.Mutex
	interval time.Duration
	next     time.Time
}

func newRateLimiter(rate int) *rateLimiter {
	if rate <= 0 {
		return &rateLimiter{}
	}
	return &rateLimiter{interval: time.Second / time.Duration(rate)}
}

func (r *rateLimiter) Wait() {
	if r.interval <= 0 {
		return
	}
	r.mu.Lock()
	now := time.Now()
	if r.next.IsZero() || !r.next.After(now) {
		r.next = now.Add(r.interval)
		r.mu.Unlock()
		return
	}
	wait := time.Until(r.next)
	r.next = r.next.Add(r.interval)
	r.mu.Unlock()
	if wait > 0 {
		time.Sleep(wait)
	}
}
EOF
