package main

import (
	"bytes"
	"compress/gzip"
	"compress/zlib"
	"context"
	"crypto/tls"
	"encoding/base64"
	"errors"
	"fmt"
	"io"
	"net"
	"net/textproto"
	"net/url"
	"strconv"
	"strings"
	"time"
)

var errTimeout = errors.New("timeout")
var errBodySize = errors.New("body size exceeds the given limit")
var errTooManyRedirects = errors.New("too many redirections")
var errLocationNotSet = errors.New("location header not set")

type retryableError struct{ err error }

func (e *retryableError) Error() string { return e.err.Error() }

func isTimeoutErr(err error) bool {
	if errors.Is(err, errTimeout) {
		return true
	}
	var ne net.Error
	if errors.As(err, &ne) && ne.Timeout() {
		return true
	}
	if errors.Is(err, context.DeadlineExceeded) {
		return true
	}
	return false
}

type headerKV struct {
	Key   string
	Value string
}

type rawResponse struct {
	Status          int
	Headers         []headerKV
	Body            []byte
	SizeExceeded    bool
	ContentType     string
	Location        string
	ContentEncoding string
}

func (r *rawResponse) headerLast(name string) string {
	v := ""
	for _, h := range r.Headers {
		if strings.EqualFold(h.Key, name) {
			v = h.Value
		}
	}
	return v
}

type acceptedCodes struct {
	singles map[int]bool
	ranges  [][2]int
}

func parseAcceptedCodes(s string) (*acceptedCodes, error) {
	ac := &acceptedCodes{singles: map[int]bool{}}
	for _, part := range strings.Split(s, ",") {
		if strings.Contains(part, "..") {
			subs := strings.Split(part, "..")
			if len(subs) != 2 {
				return nil, fmt.Errorf("invalid status code range: %s", part)
			}
			lo, err := strconv.Atoi(subs[0])
			if err != nil {
				return nil, fmt.Errorf("invalid status code: %s", subs[0])
			}
			hi, err := strconv.Atoi(subs[1])
			if err != nil {
				return nil, fmt.Errorf("invalid status code: %s", subs[1])
			}
			ac.ranges = append(ac.ranges, [2]int{lo, hi})
		} else {
			code, err := strconv.Atoi(part)
			if err != nil {
				return nil, fmt.Errorf("invalid status code range: %s", part)
			}
			ac.singles[code] = true
		}
	}
	return ac, nil
}

func (a *acceptedCodes) Contains(code int) bool {
	if a.singles[code] {
		return true
	}
	for _, r := range a.ranges {
		if code >= r[0] && code <= r[1] {
			return true
		}
	}
	return false
}

type httpClient struct {
	opts          *options
	accepted      *acceptedCodes
	customHeaders []headerKV
	globalSem     *semaphore
	hostPool      *hostThrottlerPool
	rate          *rateLimiter
}

func newHTTPClient(opts *options, accepted *acceptedCodes, headers []headerKV) *httpClient {
	return &httpClient{
		opts:          opts,
		accepted:      accepted,
		customHeaders: headers,
		globalSem:     newSemaphore(opts.MaxConnections),
		hostPool:      newHostThrottlerPool(opts.MaxConnectionsPerHost),
		rate:          newRateLimiter(opts.RateLimit),
	}
}

func (c *httpClient) effectiveBufferSize() int {
	if c.opts.BufferSize <= 0 {
		return 4096
	}
	if c.opts.BufferSize < 16 {
		return 16
	}
	return c.opts.BufferSize
}

func (c *httpClient) timeoutDuration() time.Duration {
	return time.Duration(c.opts.Timeout) * time.Second
}

// fetchWithRedirects performs redirects and returns the final response,
// its final URL, or an error. It does not apply the accepted-status check,
// body decompression, or content handling.
func (c *httpClient) fetchWithRedirects(u *url.URL) (*rawResponse, *url.URL, error) {
	current := cloneURL(u)
	followed := 0
	for {
		if followed > c.opts.MaxRedirections {
			return nil, current, errTooManyRedirects
		}
		resp, err := c.doSingle(current)
		if err != nil {
			if followed > 0 {
				err = fmt.Errorf("%s (following redirect %s)", err.Error(), current.String())
			}
			return nil, current, err
		}
		if resp.Status < 300 || resp.Status >= 400 {
			return resp, current, nil
		}
		loc := resp.Location
		if loc == "" {
			return nil, current, errLocationNotSet
		}
		ref, err := url.Parse(loc)
		if err != nil {
			return nil, current, err
		}
		current = current.ResolveReference(ref)
		followed++
	}
}

// fetchCheckedBody is used for robots.txt and sitemap.xml as well as as the
// first stage of link fetching.
func (c *httpClient) fetchCheckedBody(u *url.URL) ([]byte, *url.URL, *rawResponse, error) {
	resp, finalURL, err := c.fetchWithRedirects(u)
	if err != nil {
		return nil, finalURL, resp, err
	}
	if resp.SizeExceeded {
		return nil, finalURL, resp, errBodySize
	}
	if !c.accepted.Contains(resp.Status) {
		return nil, finalURL, resp, fmt.Errorf("%d", resp.Status)
	}
	body, err := decompressBody(resp)
	if err != nil {
		return nil, finalURL, resp, err
	}
	return body, finalURL, resp, nil
}

func decompressBody(resp *rawResponse) ([]byte, error) {
	enc := strings.Trim(resp.ContentEncoding, " \t")
	switch enc {
	case "", "identity":
		return resp.Body, nil
	case "gzip":
		r, err := gzip.NewReader(bytes.NewReader(resp.Body))
		if err != nil {
			return nil, err
		}
		defer r.Close()
		b, err := io.ReadAll(r)
		if err != nil {
			return nil, err
		}
		return b, nil
	case "deflate":
		r, err := zlib.NewReader(bytes.NewReader(resp.Body))
		if err != nil {
			return nil, err
		}
		defer r.Close()
		b, err := io.ReadAll(r)
		if err != nil {
			return nil, err
		}
		return b, nil
	case "br":
		return nil, errors.New("brotli: unsupported encoding")
	default:
		return resp.Body, nil
	}
}

func cloneURL(u *url.URL) *url.URL {
	v := *u
	if u.User != nil {
		user := *u.User
		v.User = &user
	}
	return &v
}

func (c *httpClient) doSingle(u *url.URL) (*rawResponse, error) {
	c.globalSem.Request()
	defer c.globalSem.Release()
	ht := c.hostPool.Get(u.Hostname())
	ht.Request()
	defer ht.Release()
	c.rate.Wait()

	var lastErr error
	for attempt := 0; attempt < 5; attempt++ {
		resp, err := c.doAttempt(u)
		if err == nil {
			return resp, nil
		}
		lastErr = err
		var re *retryableError
		if !errors.As(err, &re) {
			break
		}
	}
	return nil, lastErr
}

func validateRequestURL(u *url.URL) (scheme string, hostname string, port int, err error) {
	raw := u.String()
	scheme = strings.ToLower(u.Scheme)
	if strings.Contains(raw, "://") && scheme != "http" && scheme != "https" {
		return "", "", 0, fmt.Errorf("unsupported protocol %q. http and https are supported", scheme)
	}
	if u.Host == "" {
		return "", "", 0, errors.New("missing port in address")
	}
	if scheme == "" {
		scheme = "http"
	}
	hostport := u.Host
	hostname = u.Hostname()
	portStr := u.Port()
	def := 80
	if scheme == "https" {
		def = 443
	}
	if strings.HasPrefix(hostport, ":") {
		return "", "", 0, fmt.Errorf("address %s:%d: too many colons in address", hostport, def)
	}
	if strings.HasSuffix(hostport, ":") {
		_, aerr := strconv.Atoi("")
		return "", "", 0, aerr
	}
	if !strings.HasPrefix(hostport, "[") && strings.Count(hostport, ":") > 1 {
		return "", "", 0, fmt.Errorf("address %s: too many colons in address", hostport)
	}
	if portStr == "" {
		port = def
	} else {
		p, aerr := strconv.Atoi(portStr)
		if aerr != nil {
			return "", "", 0, aerr
		}
		if p > 65535 {
			return "", "", 0, fmt.Errorf("error when dialing %s: dial tcp: address %s: invalid port", hostport, portStr)
		}
		port = p
	}
	return scheme, hostname, port, nil
}

func (c *httpClient) resolver() *net.Resolver {
	if c.opts.DNSResolver == "" {
		return net.DefaultResolver
	}
	custom := c.opts.DNSResolver
	return &net.Resolver{
		PreferGo: true,
		Dial: func(ctx context.Context, network, address string) (net.Conn, error) {
			var d net.Dialer
			return d.DialContext(ctx, "udp", custom)
		},
	}
}

func (c *httpClient) dialDirect(ctx context.Context, hostname string, port int) (net.Conn, error) {
	hostname = strings.ToLower(hostname)
	if ip := net.ParseIP(hostname); ip != nil {
		addr := net.JoinHostPort(ip.String(), strconv.Itoa(port))
		var d net.Dialer
		conn, err := d.DialContext(ctx, "tcp", addr)
		if err != nil {
			if isTimeoutErr(err) {
				return nil, errTimeout
			}
			return nil, fmt.Errorf("error when dialing %s: %s", addr, err.Error())
		}
		return conn, nil
	}
	ips, err := c.resolver().LookupIP(ctx, "ip", hostname)
	if err != nil {
		if isTimeoutErr(err) {
			return nil, errTimeout
		}
		return nil, err
	}
	if len(ips) == 0 {
		return nil, fmt.Errorf("lookup %s: no such host", hostname)
	}
	var firstAddr string
	var firstErr error
	for _, ip := range ips {
		addr := net.JoinHostPort(ip.String(), strconv.Itoa(port))
		var d net.Dialer
		conn, derr := d.DialContext(ctx, "tcp", addr)
		if derr == nil {
			return conn, nil
		}
		if isTimeoutErr(derr) {
			return nil, errTimeout
		}
		if firstErr == nil {
			firstAddr = addr
			firstErr = derr
		}
	}
	return nil, fmt.Errorf("error when dialing %s: %s", firstAddr, firstErr.Error())
}

type proxyInfo struct {
	use       bool
	hostport  string // host:port as used in error messages and dialing
	auth      string // full userinfo (user:pass) or empty
	rawError  error  // error to return before dialing
	lookupRaw string // hostname to look up verbatim (for odd inputs)
}

func (c *httpClient) getProxyInfo() proxyInfo {
	proxy := c.opts.Proxy
	if proxy == "" {
		return proxyInfo{}
	}
	hadScheme := false
	part := proxy
	if idx := strings.Index(proxy, "://"); idx >= 0 {
		hadScheme = true
		scheme := strings.ToLower(proxy[:idx])
		if scheme != "http" {
			return proxyInfo{}
		}
		part = proxy[idx+3:]
		if _, err := url.Parse(proxy); err != nil {
			// e.g. http://host:abc -- observed to surface as a
			// too-many-colons address error with the full string.
			if strings.Count(proxy, ":") > 1 {
				return proxyInfo{rawError: fmt.Errorf("address %s: too many colons in address", proxy)}
			}
			return proxyInfo{rawError: fmt.Errorf("address %s: missing port in address", proxy)}
		}
	} else {
		if _, err := url.Parse("http://" + part); err != nil {
			// Invalid port and similar inputs silently fall back to a
			// direct connection in the observed behaviour.
			return proxyInfo{}
		}
	}
	_ = hadScheme
	auth := ""
	hostport := part
	if at := strings.LastIndex(part, "@"); at >= 0 {
		authPart := part[:at]
		hostport = part[at+1:]
		// Prefer URL-canonical userinfo when it parses.
		if pu, err := url.Parse("http://" + part); err == nil && pu.User != nil {
			auth = pu.User.String()
		} else {
			auth = authPart
		}
	}
	return proxyInfo{use: true, hostport: hostport, auth: auth}
}

func (c *httpClient) dialProxy(ctx context.Context, pi proxyInfo, targetHostport string) (net.Conn, error) {
	hostport := pi.hostport
	// Port extraction errors mimic the observed Atoi failures.
	colon := strings.LastIndex(hostport, ":")
	if colon < 0 {
		return nil, fmt.Errorf("address %s: missing port in address", hostport)
	}
	portSeg := hostport[colon+1:]
	port, err := strconv.Atoi(portSeg)
	if err != nil {
		return nil, err
	}
	host := hostport[:colon]
	if port > 65535 {
		return nil, fmt.Errorf("error when dialing %s: dial tcp: address %s: invalid port", hostport, portSeg)
	}
	var conn net.Conn
	if ip := net.ParseIP(host); ip != nil {
		network := "tcp4"
		if ip.To4() == nil {
			network = "tcp6"
		}
		addr := net.JoinHostPort(ip.String(), strconv.Itoa(port))
		var d net.Dialer
		cc, derr := d.DialContext(ctx, network, addr)
		if derr != nil {
			if isTimeoutErr(derr) {
				return nil, errTimeout
			}
			return nil, fmt.Errorf("error when dialing %s: %s", hostport, derr.Error())
		}
		conn = cc
	} else {
		ips, lerr := c.resolver().LookupIP(ctx, "ip", strings.ToLower(host))
		if lerr != nil {
			if isTimeoutErr(lerr) {
				return nil, errTimeout
			}
			return nil, lerr
		}
		if len(ips) == 0 {
			return nil, fmt.Errorf("lookup %s: no such host", host)
		}
		var firstErr error
		var firstAddr string
		for _, ip := range ips {
			network := "tcp4"
			if ip.To4() == nil {
				network = "tcp6"
			}
			addr := net.JoinHostPort(ip.String(), strconv.Itoa(port))
			var d net.Dialer
			cc, derr := d.DialContext(ctx, network, addr)
			if derr == nil {
				conn = cc
				break
			}
			if isTimeoutErr(derr) {
				return nil, errTimeout
			}
			if firstErr == nil {
				firstErr = derr
				firstAddr = addr
			}
		}
		if conn == nil {
			return nil, fmt.Errorf("error when dialing %s: %s", hostport, firstErr.Error())
		}
		_ = firstAddr
	}
	// CONNECT request.
	var sb strings.Builder
	sb.WriteString("CONNECT " + targetHostport + " HTTP/1.1\r\n")
	sb.WriteString("Host: " + targetHostport + "\r\n")
	if pi.auth != "" {
		sb.WriteString("Proxy-Authorization: Basic " + base64.StdEncoding.EncodeToString([]byte(pi.auth)) + "\r\n")
	}
	sb.WriteString("\r\n")
	if _, err := io.WriteString(conn, sb.String()); err != nil {
		conn.Close()
		if isTimeoutErr(err) {
			return nil, errTimeout
		}
		return nil, err
	}
	// Read status line and headers.
	cr := newConnReader(conn, nil, c.effectiveBufferSize())
	statusLine, err := cr.readLineCRLF()
	if err != nil {
		conn.Close()
		if isTimeoutErr(err) {
			return nil, errTimeout
		}
		if errors.Is(err, io.EOF) {
			return nil, errors.New("the server closed connection before returning the first response byte. Make sure the server returns 'Connection: close' response header before closing the connection")
		}
		return nil, err
	}
	// statusLine has no trailing CRLF.
	code := 0
	if idx := strings.IndexByte(statusLine, ' '); idx >= 0 && idx+1 < len(statusLine) {
		rest := statusLine[idx+1:]
		digits := 0
		for digits < len(rest) && rest[digits] >= '0' && rest[digits] <= '9' {
			digits++
		}
		if digits > 0 {
			code, _ = strconv.Atoi(rest[:digits])
		}
	}
	// Consume headers until blank line.
	for {
		line, err := cr.readLineCRLF()
		if err != nil {
			conn.Close()
			if isTimeoutErr(err) {
				return nil, errTimeout
			}
			return nil, err
		}
		if line == "" {
			break
		}
	}
	if code != 200 {
		conn.Close()
		return nil, fmt.Errorf("could not connect to proxyAddr: %s status code: %d", pi.hostport, code)
	}
	// Preserve bytes buffered beyond the CONNECT response.
	leftover := cr.remaining()
	return &bufferedConn{Conn: conn, initial: leftover}, nil
}

type bufferedConn struct {
	net.Conn
	initial []byte
}

func (b *bufferedConn) Read(p []byte) (int, error) {
	if len(b.initial) > 0 {
		n := copy(p, b.initial)
		b.initial = b.initial[n:]
		return n, nil
	}
	return b.Conn.Read(p)
}

func (c *httpClient) doAttempt(u *url.URL) (*rawResponse, error) {
	if c.opts.Timeout <= 0 {
		return nil, errTimeout
	}
	scheme, hostname, port, err := validateRequestURL(u)
	if err != nil {
		return nil, err
	}
	timeout := c.timeoutDuration()
	ctx, cancel := context.WithTimeout(context.Background(), timeout)
	defer cancel()
	deadline := time.Now().Add(timeout)

	pi := c.getProxyInfo()
	if pi.rawError != nil {
		return nil, pi.rawError
	}
	var conn net.Conn
	if pi.use {
		targetHostport := net.JoinHostPort(strings.ToLower(hostname), strconv.Itoa(port))
		// JoinHostPort with an IPv4/hostname leaves it unchanged; for a
		// plain hostname it returns host:port as desired.
		if !strings.Contains(hostname, ":") {
			targetHostport = strings.ToLower(hostname) + ":" + strconv.Itoa(port)
		}
		cc, perr := c.dialProxy(ctx, pi, targetHostport)
		if perr != nil {
			return nil, perr
		}
		conn = cc
	} else {
		cc, derr := c.dialDirect(ctx, hostname, port)
		if derr != nil {
			return nil, derr
		}
		conn = cc
	}
	defer conn.Close()
	_ = conn.SetDeadline(deadline)

	if scheme == "https" {
		tlsCfg := &tls.Config{
			InsecureSkipVerify: c.opts.SkipTLSVerification,
			ServerName:         strings.ToLower(hostname),
		}
		tconn := tls.Client(conn, tlsCfg)
		if err := tconn.HandshakeContext(ctx); err != nil {
			if isTimeoutErr(err) {
				return nil, errTimeout
			}
			return nil, err
		}
		conn = tconn
		_ = conn.SetDeadline(deadline)
	}

	// Build request.
	hostHeader := strings.ToLower(u.Host)
	reqURI := requestURIFor(u)
	var sb strings.Builder
	sb.WriteString("GET " + reqURI + " HTTP/1.1\r\n")
	sb.WriteString("Host: " + hostHeader + "\r\n")
	hasAccept := false
	hasConnection := false
	for _, h := range c.customHeaders {
		if strings.EqualFold(h.Key, "Host") {
			continue
		}
		if strings.EqualFold(h.Key, "Accept") {
			hasAccept = true
		}
		if strings.EqualFold(h.Key, "Connection") {
			hasConnection = true
		}
		sb.WriteString(canonicalHeaderKey(h.Key) + ": " + strings.Trim(h.Value, " \t\r\n") + "\r\n")
	}
	if !hasAccept {
		sb.WriteString("Accept: */*\r\n")
	}
	if u.User != nil {
		sb.WriteString("Authorization: Basic " + base64.StdEncoding.EncodeToString([]byte(u.User.String())) + "\r\n")
	}
	if !hasConnection {
		sb.WriteString("Connection: close\r\n")
	}
	sb.WriteString("\r\n")
	if _, err := io.WriteString(conn, sb.String()); err != nil {
		if isTimeoutErr(err) {
			return nil, errTimeout
		}
		return nil, &retryableError{err}
	}

	cr := newConnReader(conn, nil, c.effectiveBufferSize())
	resp, err := cr.readResponse(c)
	if err != nil {
		return nil, err
	}
	return resp, nil
}

func requestURIFor(u *url.URL) string {
	path := u.EscapedPath()
	if path == "" {
		if u.RawQuery != "" {
			return "?" + u.RawQuery
		}
		return "/"
	}
	if u.RawQuery != "" {
		return path + "?" + u.RawQuery
	}
	return path
}

func canonicalHeaderKey(key string) string {
	// textproto canonicalisation returns the input unchanged when it
	// contains invalid bytes, matching the tolerant behaviour needed here.
	return textproto.CanonicalMIMEHeaderKey(key)
}

// ---------- response reader ----------

type connReader struct {
	conn     net.Conn
	initial  []byte
	buf      []byte
	eof      bool
	readErr  error
	effSize  int
}

func newConnReader(conn net.Conn, initial []byte, effSize int) *connReader {
	return &connReader{conn: conn, buf: append([]byte(nil), initial...), effSize: effSize}
}

func (cr *connReader) remaining() []byte {
	b := append([]byte(nil), cr.buf...)
	return b
}

// fillOne reads one chunk from the connection into buf.
func (cr *connReader) fillOne(max int) error {
	if cr.eof || cr.readErr != nil {
		if cr.readErr != nil {
			return cr.readErr
		}
		return io.EOF
	}
	if max <= 0 {
		max = 4096
	}
	tmp := make([]byte, max)
	n, err := cr.conn.Read(tmp)
	if n > 0 {
		cr.buf = append(cr.buf, tmp[:n]...)
	}
	if err != nil {
		if errors.Is(err, io.EOF) {
			cr.eof = true
			return io.EOF
		}
		cr.readErr = err
		return err
	}
	return nil
}

func headerErr(detail string, window []byte) error {
	return &retryableError{fmt.Errorf("error when reading response headers: %s. Buffer size=%d, contents: %q", detail, len(window), string(window))}
}

func (cr *connReader) readHeaderBlock() ([]byte, []byte, error) {
	for {
		if idx := bytes.Index(cr.buf, []byte("\r\n\r\n")); idx >= 0 {
			window := append([]byte(nil), cr.buf...)
			block := append([]byte(nil), cr.buf[:idx+4]...)
			cr.buf = append([]byte(nil), cr.buf[idx+4:]...)
			return block, window, nil
		}
		if cr.readErr != nil {
			if isTimeoutErr(cr.readErr) {
				return nil, nil, errTimeout
			}
			return nil, nil, &retryableError{cr.readErr}
		}
		if cr.eof {
			// Partial headers at EOF.
			window := append([]byte(nil), cr.buf...)
			if len(window) == 0 {
				return nil, window, &retryableError{errors.New("the server closed connection before returning the first response byte. Make sure the server returns 'Connection: close' response header before closing the connection")}
			}
			// If a recognisable header error exists, report it, else EOF.
			if detail, ok := partialHeaderError(window); ok {
				return nil, window, headerErr(detail, window)
			}
			return nil, window, headerErr("EOF", window)
		}
		if len(cr.buf) >= cr.effSize {
			window := append([]byte(nil), cr.buf[:cr.effSize]...)
			return nil, window, headerErr("small read buffer. Increase ReadBufferSize", window)
		}
		maxRead := cr.effSize - len(cr.buf)
		if maxRead > 4096 {
			maxRead = 4096
		}
		err := cr.fillOne(maxRead)
		if err != nil && !errors.Is(err, io.EOF) {
			if isTimeoutErr(err) {
				return nil, nil, errTimeout
			}
			// Read errors are handled at the top of the next iteration
			// unless it was EOF, which is recorded. Non-EOF errors are
			// recorded in readErr by fillOne.
			if cr.readErr == nil && !cr.eof {
				return nil, nil, &retryableError{err}
			}
		}
	}
}

// partialHeaderError checks a header fragment terminated by EOF for a
// status-line or header-line error that would have been reported anyway.
func partialHeaderError(window []byte) (string, bool) {
	s := string(window)
	idx := strings.Index(s, "\r\n")
	if idx < 0 {
		return "", false
	}
	line := s[:idx]
	// Skip leading blank lines.
	for line == "" {
		s = s[idx+2:]
		idx = strings.Index(s, "\r\n")
		if idx < 0 {
			return "", false
		}
		line = s[:idx]
	}
	sp := strings.IndexByte(line, ' ')
	if sp < 0 || sp+1 >= len(line) || line[sp+1] < '0' || line[sp+1] > '9' {
		return fmt.Sprintf("cannot parse response status code: unexpected first char found. Expecting 0-9. Response %q", string(window)), true
	}
	return "", false
}

func (cr *connReader) readResponse(c *httpClient) (*rawResponse, error) {
	for {
		block, window, err := cr.readHeaderBlock()
		if err != nil {
			return nil, err
		}
		resp, err := parseHeaderBlock(block, window)
		if err != nil {
			return nil, err
		}
		if resp.Status == 100 {
			continue
		}
		body, sizeExceeded, err := cr.readBody(c, resp)
		if err != nil {
			return nil, err
		}
		resp.Body = body
		resp.SizeExceeded = sizeExceeded
		return resp, nil
	}
}

func parseHeaderBlock(block []byte, window []byte) (*rawResponse, error) {
	s := string(block)
	// Strip the terminating blank line.
	s = strings.TrimSuffix(s, "\r\n\r\n")
	lines := strings.Split(s, "\r\n")
	// Skip leading blank lines.
	i := 0
	for i < len(lines) && lines[i] == "" {
		i++
	}
	if i >= len(lines) {
		return nil, headerErr("EOF", window)
	}
	statusLine := lines[i]
	i++
	sp := strings.IndexByte(statusLine, ' ')
	if sp < 0 || sp+1 >= len(statusLine) || statusLine[sp+1] < '0' || statusLine[sp+1] > '9' {
		return nil, headerErr(fmt.Sprintf("cannot parse response status code: unexpected first char found. Expecting 0-9. Response %q", string(window)), window)
	}
	code := 0
	j := sp + 1
	for j < len(statusLine) && statusLine[j] >= '0' && statusLine[j] <= '9' {
		code = code*10 + int(statusLine[j]-'0')
		j++
	}
	resp := &rawResponse{Status: code}
	prev := -1
	for ; i < len(lines); i++ {
		line := lines[i]
		if line == "" {
			continue
		}
		if (line[0] == ' ' || line[0] == '\t') && prev >= 0 {
			resp.Headers[prev].Value += " " + strings.Trim(line, " \t")
			continue
		}
		colon := strings.IndexByte(line, ':')
		if colon < 0 {
			return nil, headerErr(fmt.Sprintf("malformed MIME header: missing colon: %q", line), window)
		}
		key := line[:colon]
		rawValue := line[colon+1:]
		value := strings.Trim(rawValue, " \t")
		for k := 0; k < len(rawValue); k++ {
			b := rawValue[k]
			if (b < 0x20 && b != '\t') || b == 0x7f {
				return nil, headerErr(fmt.Sprintf("invalid header value %q", value), window)
			}
		}
		if strings.EqualFold(key, "Content-Length") {
			if errDetail := validateContentLength(value); errDetail != "" {
				return nil, headerErr(errDetail, window)
			}
		}
		resp.Headers = append(resp.Headers, headerKV{Key: key, Value: value})
		prev = len(resp.Headers) - 1
	}
	resp.ContentType = resp.headerLast("Content-Type")
	resp.ContentEncoding = resp.headerLast("Content-Encoding")
	for _, h := range resp.Headers {
		if strings.EqualFold(h.Key, "Location") {
			resp.Location = h.Value
			break
		}
	}
	return resp, nil
}

func validateContentLength(v string) string {
	if v == "" {
		return "cannot parse Content-Length: unexpected first char found. Expecting 0-9"
	}
	if v[0] < '0' || v[0] > '9' {
		return "cannot parse Content-Length: unexpected first char found. Expecting 0-9"
	}
	for i := 1; i < len(v); i++ {
		if v[i] < '0' || v[i] > '9' {
			return "cannot parse Content-Length: non-numeric chars found"
		}
	}
	if _, err := strconv.ParseUint(v, 10, 64); err != nil {
		return "cannot parse Content-Length: too long int"
	}
	return ""
}

func (cr *connReader) readChunkSizeLine() (string, error) {
	return cr.readLineCRLF()
}

func (cr *connReader) readLineCRLF() (string, error) {
	var out []byte
	for {
		if idx := bytes.Index(cr.buf, []byte("\r\n")); idx >= 0 {
			line := string(cr.buf[:idx])
			cr.buf = append([]byte(nil), cr.buf[idx+2:]...)
			return line, nil
		}
		if cr.readErr != nil {
			if isTimeoutErr(cr.readErr) {
				return "", errTimeout
			}
			return "", &retryableError{cr.readErr}
		}
		if cr.eof {
			if len(cr.buf) == 0 {
				return "", io.EOF
			}
			// Remaining data without CRLF at EOF.
			line := string(cr.buf)
			cr.buf = nil
			return line, nil
		}
		if err := cr.fillOne(4096); err != nil && !errors.Is(err, io.EOF) {
			if isTimeoutErr(err) {
				return "", errTimeout
			}
		}
	}
}

func (cr *connReader) readFull(n int) ([]byte, error) {
	out := make([]byte, 0, n)
	for len(out) < n {
		if len(cr.buf) > 0 {
			take := n - len(out)
			if take > len(cr.buf) {
				take = len(cr.buf)
			}
			out = append(out, cr.buf[:take]...)
			cr.buf = append([]byte(nil), cr.buf[take:]...)
			continue
		}
		if cr.readErr != nil {
			if isTimeoutErr(cr.readErr) {
				return out, errTimeout
			}
			return out, &retryableError{cr.readErr}
		}
		if cr.eof {
			return out, io.ErrUnexpectedEOF
		}
		if err := cr.fillOne(4096); err != nil && !errors.Is(err, io.EOF) {
			if isTimeoutErr(err) {
				return out, errTimeout
			}
		}
	}
	return out, nil
}

func (cr *connReader) readBody(c *httpClient, resp *rawResponse) ([]byte, bool, error) {
	status := resp.Status
	if (status >= 100 && status < 200) || status == 204 || status == 304 {
		return nil, false, nil
	}
	maxBody := c.opts.MaxResponseBodySize
	te := resp.headerLast("Transfer-Encoding")
	clStr := resp.headerLast("Content-Length")
	if te != "" && !strings.EqualFold(strings.Trim(te, " \t"), "identity") {
		// Chunked (or any other transfer encoding is treated as chunked).
		return cr.readChunked(maxBody)
	}
	if clStr != "" {
		cl, err := strconv.ParseInt(clStr, 10, 64)
		if err == nil {
			if maxBody > 0 && cl > int64(maxBody) {
				return nil, true, nil
			}
			if cl < 0 {
				cl = 0
			}
			body, err := cr.readFull(int(cl))
			if err != nil {
				if errors.Is(err, io.ErrUnexpectedEOF) {
					return nil, false, &retryableError{errors.New("unexpected EOF")}
				}
				return nil, false, err
			}
			return body, false, nil
		}
	}
	// Read until EOF.
	var body []byte
	sizeExceeded := false
	for {
		if len(cr.buf) > 0 {
			body = append(body, cr.buf...)
			cr.buf = nil
			if maxBody > 0 && len(body) > maxBody {
				sizeExceeded = true
				body = body[:maxBody+1]
				return body, true, nil
			}
			continue
		}
		if cr.readErr != nil {
			if isTimeoutErr(cr.readErr) {
				return nil, false, errTimeout
			}
			return nil, false, &retryableError{cr.readErr}
		}
		if cr.eof {
			return body, sizeExceeded, nil
		}
		if err := cr.fillOne(4096); err != nil && !errors.Is(err, io.EOF) {
			if isTimeoutErr(err) {
				return nil, false, errTimeout
			}
		}
	}
}

func (cr *connReader) readChunked(maxBody int) ([]byte, bool, error) {
	var body []byte
	sizeExceeded := false
	for {
		line, err := cr.readChunkSizeLine()
		if err != nil {
			if errors.Is(err, errTimeout) {
				return nil, false, errTimeout
			}
			if errors.Is(err, io.EOF) {
				return nil, false, &retryableError{errors.New("unexpected EOF")}
			}
			return nil, false, err
		}
		// Size token up to ';'.
		token := line
		if idx := strings.IndexByte(token, ';'); idx >= 0 {
			token = token[:idx]
		}
		token = strings.Trim(token, " \t")
		// Parse hexadecimal prefix.
		digits := 0
		var size int64
		for digits < len(token) {
			ch := token[digits]
			var v int64
			switch {
			case ch >= '0' && ch <= '9':
				v = int64(ch - '0')
			case ch >= 'a' && ch <= 'f':
				v = int64(ch-'a') + 10
			case ch >= 'A' && ch <= 'F':
				v = int64(ch-'A') + 10
			default:
				goto parsed
			}
			size = size*16 + v
			digits++
		}
	parsed:
		if digits == 0 {
			return nil, false, &retryableError{errors.New("empty hex number")}
		}
		if size == 0 {
			// Trailers until blank line.
			for {
				tl, err := cr.readLineCRLF()
				if err != nil {
					if errors.Is(err, errTimeout) {
						return nil, false, errTimeout
					}
					if errors.Is(err, io.EOF) {
						return body, sizeExceeded, nil
					}
					return nil, false, err
				}
				if tl == "" {
					break
				}
			}
			return body, sizeExceeded, nil
		}
		data, err := cr.readFull(int(size))
		if err != nil {
			if errors.Is(err, io.ErrUnexpectedEOF) {
				return nil, false, &retryableError{errors.New("unexpected EOF")}
			}
			return nil, false, err
		}
		if maxBody > 0 && !sizeExceeded {
			remaining := maxBody + 1 - len(body)
			if int64(len(data)) >= int64(remaining) {
				if remaining > 0 {
					body = append(body, data[:remaining]...)
				}
				sizeExceeded = true
			} else {
				body = append(body, data...)
			}
		} else if !sizeExceeded {
			body = append(body, data...)
		}
		// Expect CRLF after chunk data.
		crlf, err := cr.readFull(2)
		if err != nil {
			if errors.Is(err, io.ErrUnexpectedEOF) {
				return nil, false, &retryableError{errors.New("unexpected EOF")}
			}
			return nil, false, err
		}
		if string(crlf) != "\r\n" {
			return nil, false, &retryableError{errors.New("cannot find crlf at the end of chunk")}
		}
	}
}
