			if isTimeoutErr(cr.readErr) {
				return nil, false, errTimeout
			}
			return nil, false, &retryableError{cr.readErr}
		}
		if cr.eof {
			return body, sizeExceeded, nil
		}
		if err := cr.fillOne(4096); err != nil && !errors.Is(err, io.EOF) {
			if isTimeoutErr(err) {
				return nil, false, errTimeout
			}
		}
	}
}

func (cr *connReader) readChunked(maxBody int) ([]byte, bool, error) {
	var body []byte
	sizeExceeded := false
	for {
		line, err := cr.readChunkSizeLine()
		if err != nil {
			if errors.Is(err, errTimeout) {
				return nil, false, errTimeout
			}
			if errors.Is(err, io.EOF) {
				return nil, false, &retryableError{errors.New("unexpected EOF")}
			}
			return nil, false, err
		}
		// Size token up to ';'.
		token := line
		if idx := strings.IndexByte(token, ';'); idx >= 0 {
			token = token[:idx]
		}
		token = strings.Trim(token, " \t")
		// Parse hexadecimal prefix.
		digits := 0
		var size int64
		for digits < len(token) {
			ch := token[digits]
			var v int64
			switch {
			case ch >= '0' && ch <= '9':
				v = int64(ch - '0')
			case ch >= 'a' && ch <= 'f':
				v = int64(ch-'a') + 10
			case ch >= 'A' && ch <= 'F':
				v = int64(ch-'A') + 10
			default:
				goto parsed
			}
			size = size*16 + v
			digits++
		}
	parsed:
		if digits == 0 {
			return nil, false, &retryableError{errors.New("empty hex number")}
		}
		if size == 0 {
			// Trailers until blank line.
			for {
				tl, err := cr.readLineCRLF()
				if err != nil {
					if errors.Is(err, errTimeout) {
						return nil, false, errTimeout
					}
					if errors.Is(err, io.EOF) {
						return body, sizeExceeded, nil
					}
					return nil, false, err
				}
				if tl == "" {
					break
				}
			}
			return body, sizeExceeded, nil
		}
		data, err := cr.readFull(int(size))
		if err != nil {
			if errors.Is(err, io.ErrUnexpectedEOF) {
				return nil, false, &retryableError{errors.New("unexpected EOF")}
			}
			return nil, false, err
		}
		if maxBody > 0 && !sizeExceeded {
			remaining := maxBody + 1 - len(body)
			if int64(len(data)) >= int64(remaining) {
				if remaining > 0 {
					body = append(body, data[:remaining]...)
				}
				sizeExceeded = true
			} else {
				body = append(body, data...)
			}
		} else if !sizeExceeded {
			body = append(body, data...)
		}
		// Expect CRLF after chunk data.
		crlf, err := cr.readFull(2)
		if err != nil {
			if errors.Is(err, io.ErrUnexpectedEOF) {
				return nil, false, &retryableError{errors.New("unexpected EOF")}
			}
			return nil, false, err
		}
		if string(crlf) != "\r\n" {
			return nil, false, &retryableError{errors.New("cannot find crlf at the end of chunk")}
		}
	}
}
