	hadScheme := false
	part := proxy
	if idx := strings.Index(proxy, "://"); idx >= 0 {
		hadScheme = true
		scheme := strings.ToLower(proxy[:idx])
		if scheme != "http" {
			return proxyInfo{}
		}
		part = proxy[idx+3:]
