		if _, err := url.Parse("http://" + part); err != nil {
			// Invalid port and similar inputs silently fall back to a
			// direct connection in the observed behaviour.
			return proxyInfo{}
		}
	}
	_ = hadScheme
	auth := ""
	hostport := part
