		}
		pos = abs + 1
	}
}

func parseStartTag(s string) (*htmlTag, int, bool) {
	// s[0] == '<', s[1] is a letter.
	i := 1
	start := i
	for i < len(s) && isTagNameChar(s[i]) {
		i++
	}
	tag := &htmlTag{Name: lowerASCII(s[start:i])}
	seen := map[string]bool{}
	for {
		for i < len(s) && isHTMLWhitespace(s[i]) {
			i++
		}
		if i >= len(s) {
			return nil, 0, false
		}
		if s[i] == '>' {
			return tag, i + 1, true
		}
		if s[i] == '/' {
			if i+1 < len(s) && s[i+1] == '>' {
				tag.SelfClosing = true
				return tag, i + 2, true
			}
			i++
			continue
		}
		// Attribute name.
		astart := i
		for i < len(s) && !isHTMLWhitespace(s[i]) && s[i] != '=' && s[i] != '>' && s[i] != '/' {
			i++
		}
		aname := lowerASCII(s[astart:i])
		for i < len(s) && isHTMLWhitespace(s[i]) {
			i++
		}
		value := ""
		if i < len(s) && s[i] == '=' {
			i++
			for i < len(s) && isHTMLWhitespace(s[i]) {
				i++
			}
			if i >= len(s) {
				return nil, 0, false
			}
			if s[i] == '"' || s[i] == '\'' {
				quote := s[i]
				i++
				vstart := i
				for i < len(s) && s[i] != quote {
					i++
				}
				if i >= len(s) {
					return nil, 0, false
				}
				value = s[vstart:i]
				i++
			} else {
				vstart := i
				for i < len(s) && !isHTMLWhitespace(s[i]) && s[i] != '>' {
					i++
				}
				value = s[vstart:i]
			}
		}
		if aname != "" && !seen[aname] {
			seen[aname] = true
			tag.Attrs = append(tag.Attrs, headerKV{Key: aname, Value: stdhtml.UnescapeString(value)})
		}
	}
}

func isASCIILetter(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

func isTagNameChar(c byte) bool {
	return !isHTMLWhitespace(c) && c != '/' && c != '>'
}

func isHTMLWhitespace(c byte) bool {
	return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f'
}

func lowerASCII(s string) string {
	b := []byte(s)
	for i, c := range b {
		if c >= 'A' && c <= 'Z' {
			b[i] = c + ('a' - 'A')
		}
	}
	return string(b)
}
