package main

import (
	"net/url"
	"regexp"
	"strings"
)

type robotsRule struct {
	Allow   bool
	Pattern string
}

type robotsGroup struct {
	Agents []string
	Rules  []robotsRule
	hasRule bool
}

type robotsData struct {
	groups []*robotsGroup
}

func parseRobots(body []byte) *robotsData {
	r := &robotsData{}
	var cur *robotsGroup
	for _, line := range strings.Split(string(body), "\n") {
		line = strings.TrimSuffix(line, "\r")
		if idx := strings.Index(line, "#"); idx >= 0 {
			line = line[:idx]
		}
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		colon := strings.Index(line, ":")
		if colon < 0 {
			continue
		}
		field := strings.ToLower(strings.TrimSpace(line[:colon]))
		value := strings.TrimSpace(line[colon+1:])
		switch field {
		case "user-agent":
			if cur == nil || cur.hasRule {
				cur = &robotsGroup{}
				r.groups = append(r.groups, cur)
			}
			cur.Agents = append(cur.Agents, value)
		case "allow", "disallow":
			if cur == nil {
				cur = &robotsGroup{}
				r.groups = append(r.groups, cur)
			}
			cur.hasRule = true
			if value == "" {
				continue
			}
			cur.Rules = append(cur.Rules, robotsRule{Allow: field == "allow", Pattern: value})
		}
	}
	return r
}

func (r *robotsData) groupForAgent(agent string) *robotsGroup {
	for _, g := range r.groups {
		for _, a := range g.Agents {
			if a == agent {
				return g
			}
		}
	}
	for _, g := range r.groups {
		for _, a := range g.Agents {
			if a == "*" {
				return g
			}
		}
	}
	return nil
}

func robotsPatternMatches(pattern, path string) bool {
	anchored := strings.HasSuffix(pattern, "$")
	pat := pattern
	if anchored {
		pat = pat[:len(pat)-1]
	}
	var sb strings.Builder
	sb.WriteString("^")
	for i, seg := range strings.Split(pat, "*") {
		if i > 0 {
			sb.WriteString(".*")
		}
		sb.WriteString(regexp.QuoteMeta(seg))
	}
	if anchored {
		sb.WriteString("$")
	}
	re, err := regexp.Compile(sb.String())
	if err != nil {
		return false
	}
	return re.MatchString(path)
}

// Allowed reports whether the given page URL may be scraped.
func (r *robotsData) Allowed(pageURL string) bool {
	if r == nil {
		return true
	}
	g := r.groupForAgent("muffet")
	if g == nil {
		return true
	}
	path := ""
	if u, err := url.Parse(pageURL); err == nil {
		path = u.Path
	}
	if path == "" {
		path = "/"
	}
	bestLen := -1
	allowed := true
	for _, rule := range g.Rules {
		if !robotsPatternMatches(rule.Pattern, path) {
			continue
		}
		if len(rule.Pattern) > bestLen {
			bestLen = len(rule.Pattern)
			allowed = rule.Allow
		}
	}
	return allowed
}
EOF
