{"command":"cat > command.go <<'EOF'
package main

import (
	"bytes"
	"encoding/xml"
	"fmt"
	"net/url"
	"regexp"
	"strings"
	"sync"
)

type headerInput struct {
	raw []string
}

type command struct {
	opts     *options
	format   string
	verbose  bool
	client   *httpClient
	fetcher  *linkFetcher
	excludes []*regexp.Regexp
	includes []*regexp.Regexp
	robots   *robotsData
	sitemap  map[string]bool
	hasSitemap bool
}

func newCommand(opts *options) *command {
	return &command{opts: opts}
}

func (cmd *command) run(rootArg string) (bool, error) {
	opts := cmd.opts
	// Resolve output format, including deprecated flags.
	format := opts.Format
	verbose := opts.Verbose
	if opts.JSON {
		format = "json"
		if opts.ExperimentalVerboseJSON {
			verbose = true
		}
	} else if opts.JUnit {
		format = "junit"
	}
	cmd.format = format
	cmd.verbose = verbose

	for _, p := range opts.Exclude {
		re, err := regexp.Compile(p)
		if err != nil {
			return false, err
		}
		cmd.excludes = append(cmd.excludes, re)
	}
	for _, p := range opts.Include {
		re, err := regexp.Compile(p)
		if err != nil {
			return false, err
		}
		cmd.includes = append(cmd.includes, re)
	}

	var headers []headerKV
	for _, h := range opts.Headers {
		idx := strings.Index(h, ":")
		if idx < 0 {
			return false, fmt.Errorf("invalid header format")
		}
		headers = append(headers, headerKV{Key: h[:idx], Value: h[idx+1:]})
	}

	accepted, err := parseAcceptedCodes(opts.AcceptedStatusCodes)
	if err != nil {
		return false, err
	}

	if format == "junit" && verbose {
		return false, fmt.Errorf("verbose option not supported for JUnit output")
	}

	cmd.client = newHTTPClient(opts, accepted, headers)
	cmd.fetcher = newLinkFetcher(cmd.client, opts)

	_, rootPage, err := cmd.fetcher.Fetch(rootArg)
	if err != nil {
		return false, fmt.Errorf("failed to fetch root page: %w", err)
	}
	if rootPage == nil {
		return false, fmt.Errorf("root page has invalid content type")
	}

	// robots.txt
	if opts.FollowRobotsTxt {
		robotsURL := originURL(rootPage.URL, "/robots.txt")
		parsed, _ := url.Parse(robotsURL)
		body, _, _, err := cmd.client.fetchCheckedBody(parsed)
		if err != nil {
			return false, fmt.Errorf("failed to fetch robots.txt: %w", err)
		}
		cmd.robots = parseRobots(body)
	}
	// sitemap.xml
	if opts.FollowSitemapXML {
		sitemapURL := originURL(rootPage.URL, "/sitemap.xml")
		parsed, _ := url.Parse(sitemapURL)
		body, _, _, err := cmd.client.fetchCheckedBody(parsed)
		if err != nil {
			return false, fmt.Errorf("failed to GET sitemap.xml: %w", err)
		}
		cmd.sitemap = parseSitemap(body)
		cmd.hasSitemap = true
	}

	crawler := newCrawler(cmd, rootPage)
	results := crawler.crawl()

	failed := false
	for _, p := range results {
		for _, l := range p.Links {
			if l.Error != "" {
				failed = true
			}
		}
	}

	switch format {
	case "json":
		printJSON(results, verbose)
	case "junit":
		printJUnit(results)
	default:
		printText(results, verbose, cmd.useColor())
	}
	return failed, nil
}

func (cmd *command) useColor() bool {
	switch cmd.opts.Color {
	case "always":
		return true
	case "never":
		return false
	default:
		return isTerminal()
	}
}

func originURL(pageURLStr, path string) string {
	u, err := url.Parse(pageURLStr)
	if err != nil {
		return path
	}
	return u.Scheme + "://" + u.Host + path
}

func parseSitemap(body []byte) map[string]bool {
	set := map[string]bool{}
	dec := xml.NewDecoder(bytes.NewReader(body))
	for {
		tok, err := dec.Token()
		if err != nil {
			break
		}
		switch t := tok.(type) {
		case xml.StartElement:
			if t.Name.Local == "loc" {
				var text string
				// Accumulate character data until the end of <loc>.
				for {
					tok2, err := dec.Token()
					if err != nil {
						text = ""
						goto done
					}
					switch tt := tok2.(type) {
					case xml.CharData:
						text += string(tt)
					case xml.EndElement:
						goto locDone
					}
				}
			locDone:
				set[text] = true
			}
		}
	}
done:
	return set
}

// ---------- crawler ----------

type linkResult struct {
	URL    string
	Status int
	Error  string
}

type pageResult struct {
	URL   string
	Links []linkResult
}

type crawlJob struct {
	result *pageResult
	page   *fetchedPage
}

type candidateJob struct {
	url  string
	page *fetchedPage
}

type crawler struct {
	cmd          *command
	rootPage     *fetchedPage
	rootHostname string
	pages        []*pageResult
	visited      map[string]bool
	mu           sync.Mutex
}

func newCrawler(cmd *command, rootPage *fetchedPage) *crawler {
	hostname := ""
	if u, err := url.Parse(rootPage.URL); err == nil {
		hostname = u.Hostname()
	}
	return &crawler{cmd: cmd, rootPage: rootPage, rootHostname: hostname, visited: map[string]bool{}}
}

func (cr *crawler) crawl() []*pageResult {
	rootResult := &pageResult{URL: cr.rootPage.URL}
	cr.pages = append(cr.pages, rootResult)
	cr.visited[cr.rootPage.URL] = true
	queue := []crawlJob{{result: rootResult, page: cr.rootPage}}
	for len(queue) > 0 {
		// Process this level in parallel.
		cands := make([][]candidateJob, len(queue))
		var wg sync.WaitGroup
		for idx, job := range queue {
			wg.Add(1)
			go func(idx int, job crawlJob) {
				defer wg.Done()
				cands[idx] = cr.processPage(job)
			}(idx, job)
		}
		wg.Wait()
		var next []crawlJob
		for _, list := range cands {
			for _, cand := range list {
				if cr.visited[cand.url] {
					continue
				}
				cr.visited[cand.url] = true
				res := &pageResult{URL: cand.url}
				cr.pages = append(cr.pages, res)
				next = append(next, crawlJob{result: res, page: cand.page})
			}
		}
		queue = next
	}
	return cr.pages
}

type linkOutcome struct {
	skip      bool
	result    linkResult
	candidate *candidateJob
}

func (cr *crawler) processPage(job crawlJob) []candidateJob {
	page := job.page
	outcomes := make([]linkOutcome, len(page.Candidates))
	var wg sync.WaitGroup
	for idx, raw := range page.Candidates {
		wg.Add(1)
		go func(idx int, raw string) {
			defer wg.Done()
			outcomes[idx] = cr.processLink(page, raw)
		}(idx, raw)
	}
	wg.Wait()

	var candidates []candidateJob
	seenCandidate := map[string]bool{}
	seenLink := map[string]bool{}
	for _, oc := range outcomes {
		if oc.skip {
			continue
		}
		key := oc.result.URL
		if oc.result.Error != "" {
			// Error results are keyed by their displayed URL, which for
			// parse errors is the raw candidate; processLink already
			// applied de-duplication there. Use URL+error as key so a
			// parse error does not suppress a distinct good link with
			// the same text (not possible in practice) -- simply dedup
			// on the pair.
			key = oc.result.URL + "\x00" + oc.result.Error
		}
		if seenLink[key] {
			continue
		}
		seenLink[key] = true
		job.result.Links = append(job.result.Links, oc.result)
		if oc.candidate != nil && !seenCandidate[oc.candidate.url] {
			seenCandidate[oc.candidate.url] = true
			candidates = append(candidates, *oc.candidate)
		}
	}
	return candidates
}

func (cr *crawler) processLink(page *fetchedPage, raw string) linkOutcome {
	trimmed := strings.TrimSpace(raw)
	if trimmed == "" {
		return linkOutcome{skip: true}
	}
	ref, err := url.Parse(trimmed)
	if err != nil {
		return linkOutcome{result: linkResult{URL: trimmed, Error: err.Error()}}
	}
	resolved := page.BaseObj.ResolveReference(ref)
	if resolved.Scheme != "http" && resolved.Scheme != "https" {
		return linkOutcome{skip: true}
	}
	resolvedStr := resolved.String()
	// URL filters.
	for _, re := range cr.cmd.excludes {
		if re.MatchString(resolvedStr) {
			return linkOutcome{skip: true}
		}
	}
	if len(cr.cmd.includes) > 0 {
		ok := false
		for _, re := range cr.cmd.includes {
			if re.MatchString(resolvedStr) {
				ok = true
				break
			}
		}
		if !ok {
			return linkOutcome{skip: true}
		}
	}
	status, fetched, ferr := cr.cmd.fetcher.FetchParsed(resolved)
	if ferr != nil {
		return linkOutcome{result: linkResult{URL: resolvedStr, Error: ferr.Error()}}
	}
	oc := linkOutcome{result: linkResult{URL: resolvedStr, Status: status}}
	// Candidate page?
	if fetched != nil && !cr.cmd.opts.OnePageOnly {
		if resolved.Hostname() == cr.rootHostname {
			if u, err := url.Parse(fetched.URL); err == nil && u.Hostname() == cr.rootHostname {
				allowed := true
				if cr.cmd.robots != nil && !cr.cmd.robots.Allowed(fetched.URL) {
					allowed = false
				}
				if allowed && cr.cmd.hasSitemap && !cr.cmd.sitemap[fetched.URL] {
					allowed = false
				}
				if allowed {
					oc.candidate = &candidateJob{url: fetched.URL, page: fetched}
				}
			}
		}
	}
	return oc
}
EOF
