)

func isTerminal() bool {
	fi, err := os.Stdout.Stat()
	if err != nil {
		return false
	}
	return fi.Mode()&os.ModeCharDevice != 0
}

func printText(pages []*pageResult, verbose bool, color bool) {
	for _, p := range pages {
		var links []linkResult
		for _, l := range p.Links {
			if verbose || l.Error != "" {
				links = append(links, l)
			}
		}
		if len(links) == 0 && !verbose {
			continue
		}
		if len(p.Links) == 0 && !verbose {
			continue
		}
		// In non-verbose mode pages with no failing links are omitted;
		// the filtered list above already handles that. In verbose mode
		// every page is printed, even with no links.
		if !verbose && len(links) == 0 {
			continue
		}
		sorted := append([]linkResult(nil), links...)
		sort.SliceStable(sorted, func(i, j int) bool {
			ci, cj := linkColumn(sorted[i]), linkColumn(sorted[j])
			if ci != cj {
				return ci < cj
			}
			return sorted[i].URL < sorted[j].URL
		})
		if color {
			fmt.Fprintf(os.Stdout, "\x1b[33m%s\x1b[0m\n", p.URL)
		} else {
			fmt.Fprintln(os.Stdout, p.URL)
		}
		for _, l := range sorted {
			col := linkColumn(l)
			if color {
				if l.Error != "" {
					fmt.Fprintf(os.Stdout, "\t\x1b[31m%s\x1b[0m\t%s\n", col, l.URL)
				} else {
					fmt.Fprintf(os.Stdout, "\t\x1b[32m%s\x1b[0m\t%s\n", col, l.URL)
				}
			} else {
				fmt.Fprintf(os.Stdout, "\t%s\t%s\n", col, l.URL)
			}
		}
	}
}

func linkColumn(l linkResult) string {
	if l.Error != "" {
		return l.Error
	}
	return fmt.Sprintf("%d", l.Status)
}

type jsonLink struct {
	URL    string `json:"url"`
	Status *int   `json:"status,omitempty"`
	Error  string `json:"error,omitempty"`
}

type jsonPage struct {
	URL   string     `json:"url"`
	Links []jsonLink `json:"links"`
}

func printJSON(pages []*pageResult, verbose bool) {
	out := []jsonPage{}
	for _, p := range pages {
		links := []jsonLink{}
		hasError := false
		for _, l := range p.Links {
			if l.Error != "" {
				hasError = true
			}
			if !verbose && l.Error == "" {
				continue
			}
			jl := jsonLink{URL: l.URL}
			if l.Error != "" {
				jl.Error = l.Error
			} else {
				st := l.Status
				jl.Status = &st
			}
			links = append(links, jl)
		}
		if !verbose && !hasError {
			continue
		}
		out = append(out, jsonPage{URL: p.URL, Links: links})
	}
	b, _ := json.Marshal(out)
	os.Stdout.Write(b)
	os.Stdout.Write([]byte("\n"))
}

type junitFailure struct {
	Message string `xml:"message,attr"`
}

type junitTestCase struct {
	Name      string        `xml:"name,attr"`
	Classname string        `xml:"classname,attr"`
	Failure   *junitFailure `xml:"failure,omitempty"`
}

type junitTestSuite struct {
	Name     string          `xml:"name,attr"`
	Tests    int             `xml:"tests,attr"`
	Failures int             `xml:"failures,attr"`
	Skipped  int             `xml:"skipped,attr"`
	Cases    []junitTestCase `xml:"testcase"`
}

type junitTestSuites struct {
	XMLName xml.Name         `xml:"testsuites"`
	Suites  []junitTestSuite `xml:"testsuite"`
}

func printJUnit(pages []*pageResult) {
	suites := junitTestSuites{}
	for _, p := range pages {
		suite := junitTestSuite{Name: p.URL, Tests: len(p.Links)}
		for _, l := range p.Links {
			tc := junitTestCase{Name: l.URL, Classname: p.URL}
			if l.Error != "" {
				suite.Failures++
				tc.Failure = &junitFailure{Message: l.Error}
			}
			suite.Cases = append(suite.Cases, tc)
		}
		suites.Suites = append(suites.Suites, suite)
	}
	b, _ := xml.MarshalIndent(suites, "", "  ")
	fmt.Fprint(os.Stdout, "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n")
	os.Stdout.Write(b)
	os.Stdout.Write([]byte("\n"))
}
EOF
