//go:build brotli

package main

/*
#cgo LDFLAGS: -l:libbrotlidec.so.1 -l:libbrotlicommon.so.1
#include <stdlib.h>
#include <string.h>

typedef struct BrotliDecoderStateStruct BrotliDecoderState;
BrotliDecoderState* BrotliDecoderCreateInstance(void* alloc_func, void* free_func, void* opaque);
void BrotliDecoderDestroyInstance(BrotliDecoderState* state);
int BrotliDecoderDecompressStream(BrotliDecoderState* state, size_t* available_in, const unsigned char** next_in, size_t* available_out, unsigned char** next_out, size_t* total_out);
int BrotliDecoderIsFinished(BrotliDecoderState* state);
int BrotliDecoderGetErrorCode(BrotliDecoderState* state);
const char* BrotliDecoderErrorString(int code);
*/
import "C"
import (
	"errors"
	"fmt"
	"io"
	"unsafe"
)

func decompressBrotli(data []byte) ([]byte, error) {
	state := C.BrotliDecoderCreateInstance(nil, nil, nil)
	if state == nil {
		return nil, errors.New("brotli: failed to create decoder")
	}
	defer C.BrotliDecoderDestroyInstance(state)

	out := make([]byte, 0, len(data)*4+1024)
	var inPtr *C.uchar
	if len(data) > 0 {
		inPtr = (*C.uchar)(unsafe.Pointer(&data[0]))
	}
	availIn := C.size_t(len(data))
	for {
		// Grow output space.
		if cap(out)-len(out) < 32768 {
			newOut := make([]byte, len(out), cap(out)+32768+len(data))
			copy(newOut, out)
			out = newOut
		}
		outPtr := (*C.uchar)(unsafe.Pointer(&out[len(out):][0]))
		availOut := C.size_t(cap(out) - len(out))
		var totalOut C.size_t
		res := C.BrotliDecoderDecompressStream(state, &availIn, &inPtr, &availOut, &outPtr, &totalOut)
		produced := (cap(out) - len(out)) - int(availOut)
		newLen := len(out) + produced
		out = out[:newLen]
		switch int(res) {
		case 1: // success
			return out, nil
		case 0: // error
			code := C.BrotliDecoderGetErrorCode(state)
			msg := C.GoString(C.BrotliDecoderErrorString(code))
			return nil, fmt.Errorf("brotli: %s", msg)
		case 2: // need more input
			if availIn == 0 {
				return nil, io.ErrUnexpectedEOF
			}
			return nil, io.ErrUnexpectedEOF
		case 3: // need more output
			continue
		default:
			return nil, fmt.Errorf("brotli: decoder result %d", int(res))
		}
	}
}
