package main

import (
	"fmt"
	"os"
	"runtime"
	"strings"
	"sync"
	"time"
)

type semaphore struct {
	ch chan struct{}
}

func newSemaphore(size int) *semaphore {
	return &semaphore{make(chan struct{}, size)}
}

func (s *semaphore) Request() {
	if cap(s.ch) == 0 {
		exitDeadlock()
	}
	s.ch <- struct{}{}
}

func (s *semaphore) Release() {
	<-s.ch
}

// exitDeadlock reproduces the runtime's deadlock failure for a zero-sized
// semaphore, which otherwise can be masked by cgo runtime threads.
func exitDeadlock() {
	buf := make([]byte, 1<<16)
	n := runtime.Stack(buf, false)
	stack := string(buf[:n])
	stack = strings.Replace(stack, "[running]", "[chan send]", 1)
	lines := strings.SplitAfter(stack, "\n")
	// Drop the runtime.Stack and exitDeadlock frames (two lines each),
	// keeping the frame at the semaphore request and below.
	if len(lines) > 5 {
		lines = append(lines[:1], lines[5:]...)
	}
	fmt.Fprintf(os.Stderr, "fatal error: all goroutines are asleep - deadlock!\n\n%s", strings.Join(lines, ""))
	os.Exit(2)
}

type hostThrottler struct {
	sem *semaphore
}

func newHostThrottler(size int) *hostThrottler {
	return &hostThrottler{newSemaphore(size)}
}

func (h *hostThrottler) Request() {
	h.sem.Request()
}

func (h *hostThrottler) Release() {
	h.sem.Release()
}

type hostThrottlerPool struct {
	mu    sync.Mutex
	size  int
	items map[string]*hostThrottler
}

func newHostThrottlerPool(size int) *hostThrottlerPool {
	return &hostThrottlerPool{size: size, items: map[string]*hostThrottler{}}
}

func (p *hostThrottlerPool) Get(host string) *hostThrottler {
	p.mu.Lock()
	defer p.mu.Unlock()
	if h, ok := p.items[host]; ok {
		return h
	}
	h := newHostThrottler(p.size)
	p.items[host] = h
	return h
