func html(w http.ResponseWriter, body string) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	fmt.Fprint(w, body)
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		html(w, `<html><head><link rel="stylesheet" href="/style.css"><script src="/app.js"></script></head><body><a href="/about">about</a><a href="/missing">missing</a><a href="/about#team">team</a><a href="/about#nope">nope</a><img src="/img.png"><a href="https://127.0.0.1:18200/external">ext-https</a></body></html>`)
	})
	mux.HandleFunc("/about", func(w http.ResponseWriter, r *http.Request) {
		html(w, `<h1 id="team">Team</h1><a href="/">home</a><a href="/deep">deep</a>`)
	})
	mux.HandleFunc("/deep", func(w http.ResponseWriter, r *http.Request) { html(w, `deep`) })
	mux.HandleFunc("/style.css", func(w http.ResponseWriter, r *http.Request) { w.Header().Set("Content-Type", "text/css"); fmt.Fprint(w, "body{}") })
	mux.HandleFunc("/app.js", func(w http.ResponseWriter, r *http.Request) { w.Header().Set("Content-Type", "text/javascript"); fmt.Fprint(w, "x=1") })
	mux.HandleFunc("/img.png", func(w http.ResponseWriter, r *http.Request) { w.Header().Set("Content-Type", "image/png"); w.Write([]byte{0x89, 0x50}) })
	mux.HandleFunc("/external", func(w http.ResponseWriter, r *http.Request) { html(w, `external`) })
	mux.HandleFunc("/old", func(w http.ResponseWriter, r *http.Request) { http.Redirect(w, r, "/about", http.StatusMovedPermanently) })
	mux.HandleFunc("/sitemap.xml", func(w http.ResponseWriter, r *http.Request) { w.Header().Set("Content-Type", "application/xml"); fmt.Fprint(w, `<?xml version="1.0"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><url><loc>http://127.0.0.1:18200/about</loc></url></urlset>`) })
	mux.HandleFunc("/robots.txt", func(w http.ResponseWriter, r *http.Request) { w.Header().Set("Content-Type", "text/plain"); fmt.Fprint(w, "User-agent: *\nDisallow: /deep\n") })
	http.ListenAndServe("127.0.0.1:18200", mux)
}
EOF
