end=t.index("// Allowed reports")
new='''func robotsPatternMatches(pattern, path string) bool {
	if path == "" {
		path = "/"
	}
	anchored := strings.HasSuffix(pattern, "$")
	core := pattern
	if anchored {
		core = core[:len(core)-1]
	}
	if core == "" {
		return false
	}
	if !anchored {
		allStars := true
		for i := 0; i < len(core); i++ {
			if core[i] != '*' {
				allStars = false
				break
			}
		}
		if allStars {
			return false
		}
	}
	if !strings.HasPrefix(core, "/") && !strings.HasPrefix(core, "*") {
		core = "/" + core
	}
	type key struct{ p, s int }
	memo := map[key]bool{}
	var match func(pi, si int) bool
	match = func(pi, si int) bool {
		k := key{pi, si}
		if v, ok := memo[k]; ok {
			return v
		}
		var res bool
		defer func() { memo[k] = res }()
		if pi == len(core) {
			if anchored {
				res = si == len(path)
			} else {
				res = true
			}
			return res
		}
		if core[pi] == '*' {
			res = match(pi+1, si) || (si < len(path) && match(pi, si+1))
			return res
		}
		if si < len(path) && core[pi] == path[si] {
			res = match(pi+1, si+1)
			return res
		}
		return false
	}
	return match(0, 0)
}

