{"command":"cat > robots.go <<'EOF'
package main

import (
	"errors"
	"fmt"
	"net/url"
	"strconv"
	"strings"
)

type robotsRule struct {
	Allow   bool
	Pattern string
}

type robotsGroupData struct {
	Agents []string
	Rules  []robotsRule
}

type robotsData struct {
	Rules []robotsRule // rules of the selected (merged) groups
}

type robotsLine struct {
	Key     string
	Value   string
	HasValue bool
	NTokens int
}

func splitRobotsLine(line string) (key, value string, hasValue bool, nTokens int) {
	// Tokens for counting stop at a comment token.
	fields := []string{}
	rest := line
	for {
		rest = strings.TrimLeft(rest, " \t\r")
		if rest == "" || strings.HasPrefix(rest, "#") {
			break
		}
		idx := strings.IndexAny(rest, " \t\r")
		if idx < 0 {
			fields = append(fields, rest)
			break
		}
		fields = append(fields, rest[:idx])
		rest = rest[idx:]
	}
	nTokens = len(fields)

	s := strings.TrimLeft(line, " \t\r")
	i := 0
	start := i
	for i < len(s) && s[i] != ' ' && s[i] != '\t' && s[i] != '\r' && s[i] != ':' {
		i++
	}
	key = s[start:i]
	if i < len(s) && s[i] == ':' {
		i++
	}
	for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
		i++
	}
	if i < len(s) && s[i] == '#' {
		return key, "", false, nTokens
	}
	vstart := i
	for i < len(s) && s[i] != ' ' && s[i] != '\t' && s[i] != '\r' {
		i++
	}
	value = s[vstart:i]
	hasValue = value != ""
	return key, value, hasValue, nTokens
}

func parseRobots(body []byte) (*robotsData, error) {
	var groups []*robotsGroupData
	var cur *robotsGroupData
	curHasContent := false
	var errs []string

	tokenPos := 1
	eolRunActive := false

	lines := strings.Split(string(body), "\n")
	for _, rawLine := range lines {
		line := strings.TrimSuffix(rawLine, "\r")
		leading := strings.TrimLeft(line, " \t\r")
		if leading == "" {
			if line == "" {
				if !eolRunActive {
					tokenPos++
				}
				eolRunActive = true
			} else {
				tokenPos++
				eolRunActive = false
			}
			continue
		}
		if strings.HasPrefix(leading, "#") {
			tokenPos++
			eolRunActive = true
			continue
		}
		keyNo := tokenPos + 1
		key, value, hasValue, nTokens := splitRobotsLine(line)
		consume := nTokens + 1
		if !hasValue {
			consume = 2
			if nTokens == 0 {
				consume = 2
			}
		}
		lowerKey := strings.ToLower(key)
		switch lowerKey {
		case "user-agent":
			if cur == nil || curHasContent {
				cur = &robotsGroupData{}
				groups = append(groups, cur)
				curHasContent = false
			}
			cur.Agents = append(cur.Agents, value)
		case "allow", "disallow":
			canonical := "Allow"
			if lowerKey == "disallow" {
				canonical = "Disallow"
			}
			if cur == nil {
				errs = append(errs, fmt.Sprintf("%s before User-agent at token #%d.", canonical, keyNo))
			} else {
				curHasContent = true
				if hasValue {
					cur.Rules = append(cur.Rules, robotsRule{Allow: lowerKey == "allow", Pattern: value})
				}
			}
		case "crawl-delay":
			parseValue := value
			if !hasValue {
				parseValue = "\n"
			}
			delay, ferr := strconv.ParseFloat(parseValue, 64)
			bad := false
			if ferr != nil {
				var numErr *strconv.NumError
				if errors.As(ferr, &numErr) && errors.Is(numErr.Err, strconv.ErrRange) {
					// Out-of-range values are accepted (as infinity).
				} else {
					errs = append(errs, ferr.Error())
					bad = true
				}
			}
			if !bad && delay < 0 {
				errs = append(errs, fmt.Sprintf("Crawl-delay invalid value '%s'", parseValue))
				bad = true
			}
			if !bad {
				if cur == nil {
					errs = append(errs, fmt.Sprintf("Crawl-delay before User-agent at token #%d.", keyNo))
				} else {
					curHasContent = true
				}
			}
		default:
			// Sitemap, Host, and unknown lines have no effect.
		}
		tokenPos += consume
		eolRunActive = true
	}

	if len(errs) > 0 {
		return nil, fmt.Errorf("Parse error(s): \n%s\n", strings.Join(errs, "\n"))
	}

	// Select groups for "muffet" (case-insensitive), else "*".
	var selected []*robotsGroupData
	for _, g := range groups {
		for _, a := range g.Agents {
			if strings.EqualFold(a, "muffet") {
				selected = append(selected, g)
				break
			}
		}
	}
	if len(selected) == 0 {
		for _, g := range groups {
			for _, a := range g.Agents {
				if a == "*" {
					selected = append(selected, g)
					break
				}
			}
		}
	}
	r := &robotsData{}
	for _, g := range selected {
		r.Rules = append(r.Rules, g.Rules...)
	}
	return r, nil
}

func robotsPatternMatches(pattern, path string) bool {
	if path == "" {
		path = "/"
	}
	anchored := strings.HasSuffix(pattern, "$")
	core := pattern
	if anchored {
		core = core[:len(core)-1]
	}
	if core == "" {
		return false
	}
	if !anchored {
		allStars := true
		for i := 0; i < len(core); i++ {
			if core[i] != '*' {
				allStars = false
				break
			}
		}
		if allStars {
			return false
		}
	}
	if !strings.HasPrefix(core, "/") && !strings.HasPrefix(core, "*") {
		core = "/" + core
	}
	type key struct{ p, s int }
	memo := map[key]bool{}
	var match func(pi, si int) bool
	match = func(pi, si int) bool {
		k := key{pi, si}
		if v, ok := memo[k]; ok {
			return v
		}
		var res bool
		defer func() { memo[k] = res }()
		if pi == len(core) {
			if anchored {
				res = si == len(path)
			} else {
				res = true
			}
			return res
		}
		if core[pi] == '*' {
			res = match(pi+1, si) || (si < len(path) && match(pi, si+1))
			return res
		}
		if si < len(path) && core[pi] == path[si] {
			res = match(pi+1, si+1)
			return res
		}
		return false
	}
	return match(0, 0)
}

// Allowed reports whether the given page URL may be scraped.
func (r *robotsData) Allowed(pageURL string) bool {
	if r == nil {
		return true
	}
	path := ""
	if u, err := url.Parse(pageURL); err == nil {
		path = u.Path
	}
	if path == "" {
		path = "/"
	}
	bestLen := -1
	allowed := true
	for _, rule := range r.Rules {
		if !robotsPatternMatches(rule.Pattern, path) {
			continue
		}
		if len(rule.Pattern) > bestLen {
			bestLen = len(rule.Pattern)
			allowed = rule.Allow
		}
	}
	return allowed
}
EOF
