				if errors.As(ferr, &numErr) && errors.Is(numErr.Err, strconv.ErrRange) {
					// Out-of-range values are accepted (as infinity).
				} else {
					errs = append(errs, ferr.Error())
					bad = true
				}
			}
			if !bad && delay < 0 {
				errs = append(errs, fmt.Sprintf("Crawl-delay invalid value '%s'", parseValue))
				bad = true
			}
			if !bad {
				if cur == nil {
					errs = append(errs, fmt.Sprintf("Crawl-delay before User-agent at token #%d.", keyNo))
				} else {
					curHasContent = true
				}
			}
		default:
			// Sitemap, Host, and unknown lines have no effect.
		}
		tokenPos += consume
		eolRunActive = true
	}

	if len(errs) > 0 {
		return nil, fmt.Errorf("Parse error(s): \n%s\n", strings.Join(errs, "\n"))
	}

	// Select groups for "muffet" (case-insensitive), else "*".
	var selected []*robotsGroupData
	for _, g := range groups {
		for _, a := range g.Agents {
			if strings.EqualFold(a, "muffet") {
				selected = append(selected, g)
				break
			}
		}
	}
	if len(selected) == 0 {
		for _, g := range groups {
			for _, a := range g.Agents {
				if a == "*" {
					selected = append(selected, g)
					break
				}
			}
		}
	}
	r := &robotsData{}
	for _, g := range selected {
		r.Rules = append(r.Rules, g.Rules...)
	}
	return r, nil
}

func robotsPatternMatches(pattern, path string) bool {
	if path == "" {
		path = "/"
	}
	anchored := strings.HasSuffix(pattern, "$")
	core := pattern
	if anchored {
		core = core[:len(core)-1]
	}
	if core == "" {
		return false
	}
	if !anchored {
		allStars := true
		for i := 0; i < len(core); i++ {
			if core[i] != '*' {
				allStars = false
				break
			}
		}
		if allStars {
			return false
		}
	}
	if !strings.HasPrefix(core, "/") && !strings.HasPrefix(core, "*") {
		core = "/" + core
	}
	type key struct{ p, s int }
	memo := map[key]bool{}
	var match func(pi, si int) bool
	match = func(pi, si int) bool {
		k := key{pi, si}
		if v, ok := memo[k]; ok {
			return v
		}
		var res bool
		defer func() { memo[k] = res }()
		if pi == len(core) {
			if anchored {
				res = si == len(path)
			} else {
				res = true
			}
			return res
		}
		if core[pi] == '*' {
			res = match(pi+1, si) || (si < len(path) && match(pi, si+1))
			return res
		}
		if si < len(path) && core[pi] == path[si] {
			res = match(pi+1, si+1)
			return res
		}
		return false
	}
	return match(0, 0)
}

// Allowed reports whether the given page URL may be scraped.
func (r *robotsData) Allowed(pageURL string) bool {
	if r == nil {
		return true
	}
	path := ""
	if u, err := url.Parse(pageURL); err == nil {
		path = u.Path
	}
	if path == "" {
		path = "/"
	}
	bestLen := -1
	allowed := true
	for _, rule := range r.Rules {
		if !robotsPatternMatches(rule.Pattern, path) {
			continue
		}
		if len(rule.Pattern) > bestLen {
			bestLen = len(rule.Pattern)
			allowed = rule.Allow
		}
	}
	return allowed
}
